import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, FormControl, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { Geolocation } from '@ionic-native/geolocation/ngx';
import { AlertService } from 'src/app/services/alert.service';
import { AwsService } from 'src/app/services/emis/aws.service';


@Component({
  selector: 'app-civilbuildinglist',
  templateUrl: './civilbuildinglist.page.html',
  styleUrls: ['./civilbuildinglist.page.scss'],
})
export class CivilbuildinglistPage implements OnInit {
  dist: any;
  form: FormGroup;
  blockList: any;
  schoolList: any;
  yearList: any[];
  NoStuData: boolean;
  constructList: any;
  civilListData: any;
  districtList: any;
  data: any;
  lat: any;
  long: any;
  locationCordinates: any;
  active: boolean;
  queslist: any;
  routeData: any;
  Id: any;
  NoData: boolean;
  isbuildActive: boolean;

  constructor(
    private router: Router,private awsService: AwsService,
    private fb: FormBuilder,
    private geolocation: Geolocation,
    private route: ActivatedRoute, private alertService: AlertService
  ) { }

  ngOnInit() {
    this.initialValidator();
  }

  ionViewDidEnter() {
    this.routeData = this.route.snapshot;
    this.Id = this.routeData.queryParams.Id;
    this.getBlockList();
    this.getLatLong();
  }

  initialValidator() {
    this.form = this.fb.group({
      'district': new FormControl('', null),
      'block': new FormControl('', Validators.required),
      'year': new FormControl('', Validators.required),
      'school': new FormControl('', null)
    });
  }

  getLatLong() {
    this.geolocation.getCurrentPosition({
      enableHighAccuracy: true,
      timeout: 10000,
      maximumAge: 0
    }).then((resp) => {
      this.locationCordinates = resp.coords;
      this.lat = this.locationCordinates.latitude;
      this.long = this.locationCordinates.longitude;
    }).catch((error) => {
    });
  }

  getBlockList() {
    this.yearList = [
      { value: '2018-19', label: "2018-19" },
      { value: '2019-20', label: "2019-20" },
      { value: '2020-21', label: "2020-21" }];
    let userName = window.localStorage.getItem('username');
    this.awsService.getDistrictByUsername(userName).subscribe((res) => {
      console.log(res, "res")
      if (res) {
        this.dist = res[0].district_id;
        this.form.controls['district'].setValue(this.dist);
        this.awsService.getBlockByDistId(this.form.value.district).subscribe((res) => {
          console.log(res, "res id", this.form.value)
          if (res) {
            var data = res;
            this.blockList = data.map(l => { return { label: l.block_name, value: l.id }; });
            this.blockList.sort((a, b) => {
              if (a.label < b.label)
                return -1;
              if (a.label > b.label)
                return 1;
              return 0;
            });
          }
        });
      }
    });
    if (this.form.valid) {
      this.getCivilConstructionList();
    }
  }

  onChange() {
    this.form.controls.school.setValue('');
    if (this.form.valid) {
      this.getCivilConstructionList();
    }
  }

  getCivilConstructionList() {
    this.schoolList = [];
    this.awsService.getCivilAllocateConst(this.form.value).subscribe((res) => {
      if (res) {
        if (res[1].length > 0) {
          this.NoStuData = false;
          this.schoolList = res[1];
        }
        else {
          this.NoStuData = true;
        }
        this.civilListData = [];
        this.civilListData = res[0];
      }
    });
  }

  goToBack() {
    this.router.navigate(['/tabs/dashboard']);
  }

  goToCivilQuestions(construct) {
    //debugger
    if (this.form.valid) {
      if (this.lat && this.long) {
        var data = {
          schId: construct.school_id,
          bldtype: construct.building_type_id,
          acyear: this.form.value.year
        }
        this.awsService.getEntryStatus(data).subscribe((res) => {
          this.router.navigate(['tabs/inspectiondetails'], { queryParams: { 'surveyId': 4001, 'schoolId': this.form.value.school, 'constId': construct.building_type_id, lat: this.lat, long: this.long, acyear: this.form.value.year, Id: this.Id }, skipLocationChange: false });
          // if (res.length > 0 && res[0].remaining != 0) {
          //   this.router.navigate(['tabs/inspectiondetails'], { queryParams: { 'surveyId': 4001, 'schoolId': this.form.value.school, 'constId': construct.building_type_id, lat: this.lat, long: this.long, acyear: this.form.value.year, Id: this.Id }, skipLocationChange: false });
          // }
          // else {
          //   this.alertService.error('Already Submitted for Today');
          // }
        });
      }
      else {
        this.getLatLong();
        this.alertService.error('Please Enable Your Mobile Location');
      }
    }
  }
}

